<template><div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-logo"><i></i><i></i><i></i></span><span class="brand-name">Smart <b>CRM</b><small>{{ t('brandSub') }}</small></span></div><p class="nav-label">{{ t('menu') }}</p><nav><RouterLink v-for="item in items" :key="item.path" :to="item.path" exact-active-class="router-link-exact-active"><span class="nav-icon">{{ item.icon }}</span><span>{{ t(item.key) }}</span></RouterLink></nav><div class="sidebar-footer"><div class="user-box"><div class="avatar">{{ initials }}</div><div class="user-text"><strong>{{ user?.full_name || 'User' }}</strong><small>{{ user?.role || 'Member' }}</small></div><button class="logout" title="Logout" @click="logout">↗</button></div><div class="secure-line"><span>●</span> {{ t('secure') }}</div></div></aside><main class="content"><header><div><span class="eyebrow">SMART CRM <b>/</b> {{ pageTitle }}</span><h2>{{ pageTitle }}</h2><p class="header-subtitle">{{ t('appSubtitle') }}</p></div><div class="header-actions"><div class="language-switch"><button :class="{active:locale==='uk'}" @click="setLocale('uk')">UA</button><button :class="{active:locale==='en'}" @click="setLocale('en')">EN</button></div><div class="status-pill"><span></span> {{ t('online') }}</div></div></header><RouterView /></main></div></template>
<script setup>
import { ref, computed, onMounted } from 'vue'; import { useRouter } from 'vue-router'; import { getMe, token } from '../api'; import { locale, setLocale, t } from '../i18n'
const router = useRouter(), user = ref(null), items = [{key:'dashboard',path:'/',icon:'⌂'},{key:'customers',path:'/customers',icon:'♙'},{key:'contacts',path:'/contacts',icon:'◎'},{key:'deals',path:'/deals',icon:'◇'},{key:'activities',path:'/activities',icon:'◷'}]; const pageTitle = computed(() => router.currentRoute.value.name === 'Customer Details' ? t('details') : t(String(router.currentRoute.value.name || 'dashboard').toLowerCase())); const initials = computed(() => (user.value?.full_name || 'U').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()); onMounted(async () => { try { user.value = await getMe() } catch { token.clear(); router.push('/login') } }); function logout(){ token.clear(); router.push('/login') }
</script>
